import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"VTLA: Vision-Tactile-Language-Action Model with Preference Learning for Insertion Manipulation","description":"","frontmatter":{"title":"VTLA: Vision-Tactile-Language-Action Model with Preference Learning for Insertion Manipulation","arxiv":"2505.09577","date":"2025-05-14","authors":"Chaofan Zhang, Peng Hao, Xiaoge Cao, Xiaoshuai Hao, Shaowei Cui, Shuo Wang","categories":"cs.RO","topics":"视触觉融合, VLA, 偏好学习","outline":[2,2]},"headers":[],"relativePath":"papers/2505.09577.md","filePath":"papers/2505.09577.md","lastUpdated":null}'),e={name:"papers/2505.09577.md"};function l(i,s,r,m,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="vtla-vision-tactile-language-action-model-with-preference-learning-for-insertion-manipulation" tabindex="-1">VTLA: Vision-Tactile-Language-Action Model with Preference Learning for Insertion Manipulation <a class="header-anchor" href="#vtla-vision-tactile-language-action-model-with-preference-learning-for-insertion-manipulation" aria-label="Permalink to &quot;VTLA: Vision-Tactile-Language-Action Model with Preference Learning for Insertion Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.09577" target="_blank" rel="noreferrer">2505.09577</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-14</td></tr><tr><td><strong>作者</strong></td><td>Chaofan Zhang, Peng Hao, Xiaoge Cao, Xiaoshuai Hao, Shaowei Cui, Shuo Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把触觉图像序列拼成网格当作「时序增强 token」、把视觉放到最靠近动作的位置喂给 Qwen2-VL，再用 DPO 给离散 token 预测补上一层类回归监督，做 0.6 mm 间隙的指尖插孔。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>现有 VLA 模型的能力边界基本止于「视觉主导」的任务 —— 抓取、放置、推动。一旦进入接触密集场景（插孔、装配、拧螺栓），视觉就不够了：当销钉已经贴住孔口，末端与孔的相对偏差可能只有零点几毫米，且被夹爪和工件本身遮挡，摄像头看不见。人在这种时候靠的是手指的触觉反馈。</p><p>本文要解决的是把触觉接进 VLA 的具体形式：不是把触觉当成额外的低维状态向量拼进去，而是让语言模型同时理解视觉、触觉与指令，输出离散动作 token。任务是指尖插孔（fingertip peg-in-hole），间隙从 2.0 mm 收到 0.6 mm，训练全在仿真里做，评测要跨到真机。</p><p>重要性在于：接触密集任务是工业装配的主体，而这类任务恰好是当前通用机器人策略最薄弱的一环。如果视触觉能在一个 VLM 骨干里统一起来，就不需要为每个装配任务单独设计力控状态机。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视触觉融合</strong>这条线已经很成熟：早期特征融合、注意力融合被用在滑移检测、抓取结果预测、倒液体上；强化学习方法在插孔上也有成果（Visuotactile-RL、Lee 等的多模态表示）。它们已经能做到的是：在固定任务、固定数据集上把两种模态融好。不够的地方是范式性的 —— 这些是专有模型（proprietary models），换个销钉形状就要重训，没有语言接口，也没有跨任务泛化的机制。</p><p><strong>VLA 侧</strong>：RT-2 开创了把动作写成 token 的范式，RoboFlamingo、OpenVLA 沿用；GR-1/GR-2 用视频预训练再适配；RDT-1B、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 用扩散/流匹配生成动作序列。这些方法的共同缺口是<strong>没有触觉</strong>，所以任务停在平面推动与抓放。</p><p><strong>触觉语言模型</strong>侧：Fu 等与 Cheng 等（Touch100k）做的是触觉纹理描述与材质识别，属于「理解」而非「控制」。最接近的对手是 <strong>TLA</strong> —— 它把触觉与语言接起来生成动作，证明了触觉 token 化路线可行。本文对它的批评具体到两点：其一，TLA 的触觉编码与训练/推理框架还有改进空间；其二，<strong>没有视觉就有性能天花板</strong>，机器人缺乏全局感知。这个批评在本文实验里得到了直接支持：仿真中 TLA 在 0.6 mm 上成功率 80%，但迁到真机只剩 30–40%，而带视觉的 VLA/VTLA 都在 90% 以上。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>不用本文结论作前提。第一步观察：插孔任务的信息结构是<strong>时变</strong>的 —— 接触发生前，位置信息只能来自视觉；接触发生后，最精确的偏差信号来自触觉。这意味着两种模态不是简单互补，而是分阶段主导，前人在 RL 插孔工作里已经报告过这一现象。</p><p>第二步：VLM 的骨干是自回归语言模型，而语言模型有一个已知的<strong>近因偏置</strong>（recency bias）—— 越靠近生成位置的 token 影响越大。既然视觉在早期阶段更关键，就应该把视觉 token 摆在触觉之后、紧挨着动作输出。这是一个几乎零成本的设计决策，只需改 prompt 的拼装顺序。</p><p>第三步：触觉是一个<strong>序列</strong>（连续几个时刻的接触图像），但 VLM 对细粒度时序依赖处理得不好，而 Qwen-VL 家族的 3D 卷积视频通路是为高层语义视频设计的，与短时程低层触觉图像存在域差。绕过去的最省事办法是把时序折叠进空间 —— 把连续几帧触觉图拼成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 网格当一张图送进 ViT，让空间注意力去处理时序关系。</p><p>第四步：动作是连续量，但 NTP 损失是分类损失，它对「预测成 5 而真值是 6」和「预测成 5 而真值是 15」给同样的惩罚。要在不改架构的前提下注入距离信息，最省事的路径是用<strong>偏好</strong>：让模型自己采若干个动作，按与真值的接近程度排成 chosen/rejected 对，用 DPO 训。这样距离信息通过偏序被间接注入了。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>两句设计直觉。第一，语言模型有近因偏置，所以把最该被听见的模态（早期阶段的视觉）放在最靠近动作输出的位置，而不是按「视觉在前、触觉在后」的习惯排列。第二，机器人控制是回归问题却被写成了分类损失，缺的是「错多远」这个信息；用模型自采样构造的偏好对，可以把距离信息偷偷编码进偏序里，不动架构也不动损失形式。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一个 0.6 mm 间隙的方形销插孔为例：</p><ol><li><strong>数据生成（全仿真）</strong>。在 Isaac Gym 里搭自研视触觉仿真器，腕部相机 + 两个指尖视触觉传感器。夹爪抓住销钉悬于孔上方，注入 3-DoF 随机错位（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span>、绕 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 转）。下压尝试插入：若发生碰撞则本次失败、抬起重试；若无碰撞抵达插入深度则成功。最多 15 次尝试。用随机插入策略采数据，共 <strong>28,000</strong> 条样本，覆盖 5 种销孔形状、间隙 0.6–2.0 mm，配合域随机化（环境参数、任务配置、视觉与触觉观测）。</li><li><strong>指令化组织</strong>。每条样本 = 左右指尖触觉图序列（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 网格）+ 一张视觉图 + 一段文本指令（说明图像类型、销钉形状、动作要求）+ 动作标签，用 <code>&lt;|im_start|&gt;</code>/<code>&lt;|im_end|&gt;</code> 与 <code>&lt;|vision_start|&gt;</code>/<code>&lt;|vision_end|&gt;</code> 包装。</li><li><strong>阶段一 SFT</strong>。骨干 Qwen2-VL-7B，触觉与视觉经视觉编码器 + 模态适配器变成 token，<strong>触觉在前、视觉在后</strong>（VGTE 的核心排序），文本 token 拼上，NTP 损失微调。冻结视觉编码器与适配器，只调语言模型。lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>，batch 64，10 epoch，LlamaFactory 框架。</li><li><strong>阶段二 DPO</strong>。用阶段一模型在同一批训练样本上采两组不同生成配置的动作，按与真值的接近程度标 chosen/rejected，得到 2,400 条偏好数据。以 SFT 模型同时作为可训练策略与冻结参考模型，做 DPO，lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">6</span></span></span></span></span></span></span></span></span></span></span></span>，batch 32，3 epoch。</li><li><strong>真机部署</strong>。UR3 + Robotiq 2F-85 夹爪，腕部 RealSense D405，指尖两个 GelStereo 2.0。<strong>零微调</strong>直接跑仿真训练出的模型。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>阶段一是标准的下一 token 预测：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">NTP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.0954em;vertical-align:-1.2671em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8829em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2671em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2274em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;">)</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">.</span></span></span></span></span></p><p>这里的关键是<strong>它对动作空间的几何一无所知</strong>。动作被离散成 token 后，词表上任意两个 token 之间的「距离」都是一样的，交叉熵只惩罚「猜没猜中」。而插孔要求的是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 三个方向上的连续修正量，猜偏 0.1 mm 和猜偏 2 mm 在物理上是天壤之别。这就是作者说的「分类损失与连续控制任务之间的 gap」。</p><p>阶段二用 DPO 把距离信息以偏序形式注回来：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">DPO</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4221em;vertical-align:-0.9721em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">σ</span><span class="mspace" style="margin-right:-0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size3">(</span></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">chosen</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">chosen</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">rejected</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">rejected</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.9721em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose delimcenter" style="top:0em;"><span class="delimsizing size3">)</span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">.</span></span></span></span></span></p><p>（论文式 (2) 中第二项的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span> 未显式写出，按 DPO 原始定义两项共用同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0528em;">β</span></span></span></span>，此处按标准形式补齐。）</p><p>值得点明的是这个替换在做什么。原始 DPO 的偏好来自人类标注，编码的是「哪个回答更好」这一主观量；这里的偏好由<strong>与真值动作的 L1 距离</strong>机械生成，所以它编码的是一个确定性排序函数。这使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">DPO</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在效果上更接近一个<strong>成对排序损失（pairwise ranking loss）</strong>，作用是把策略概率质量往真值附近搬 —— 作者称之为 &quot;regression-like supervision&quot;，这个措辞是准确的。但也因此，它继承了排序损失的固有局限：只约束相对顺序，不约束绝对幅度，且监督信号的丰富程度完全由采样出的候选动作的多样性决定。作者自己在 §4.3 里也推断出了这一点（见 §7）。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：LLM 骨干比传统模仿学习强多少？</strong> 表 2（仿真，方形销，每档 50 次）：0.6 mm 间隙下 Diffusion Policy 22%，而 VLA 80%、TLA 80%、VTLA 90%。表 3 的 OOD 圆销上 DP 只有 10%，三个 LLM 方法都在 90% 以上。差距是数量级的，结论明确。</p><p><strong>问题二：视觉与触觉各自贡献什么？</strong> 视觉的贡献巨大：表 1 的 ID-GCR 上 VLA 46.1% vs TLA 15.3%。触觉的增量则要小得多：VTLA 47.3% vs VLA 46.1%，只有 1.2 个百分点；且逐维看，ID 的 L1-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 上 <strong>VLA 0.886 优于 VTLA 0.904</strong>。触觉真正体现价值的地方在任务成功率的尾部：0.6 mm 间隙从 80% 提到 90%，以及 OOD 五边形销的 92% vs 82%/80%。可以推断触觉的作用集中在「视觉已经无能为力的最后零点几毫米」，这与 §3 的分阶段直觉一致。</p><p><strong>问题三：DPO 值多少？</strong> 表 4 是全文最需要小心读的一张。ID 上 GCR 依次是 47.5（无 DPO）→ 47.5（DPO-1k）→ <strong>47.3</strong>（DPO-2k），三个 L1 只在小数点后第三位变动。OOD 上 27.0 → 31.4 → 31.2。作者概括为「在 ID 和 OOD 数据上都显著提升」，但<strong>ID 一侧的数据不支持这个说法</strong> —— 完全没有提升，2k 档还略降。摘要与正文里的「16% 提升」是相对提升（31.4/27.0 ≈ 1.163），绝对提升是 4.4 个百分点，读者需要注意口径。作者自己也如实报告了偏好数据从 1k 加到 2k 无进一步收益，并推断问题在于偏好数据只由<strong>两组采样配置</strong>生成、多样性不足 —— 这与 §6 里指出的排序损失局限完全吻合。</p><p><strong>问题四：Sim2Real 能不能过？</strong> 表 5/6（真机，UR3，每任务 20 次）：VTLA 在 1.6/1.0/0.6 mm 上是 100%/100%/95%，平均步数 1.60/1.95/4.31；OOD 形状（三角、六边、五边、圆）分别 95/95/100/100，甚至略高于 ID 的方形。表 7 的横比里 VLA 三角 90%、五边 100%，VTLA 95%/100%，两者接近；差别在效率（五边形 1.85 步 vs 2.30 步）。<strong>TLA 是唯一崩掉的</strong> —— 真机 30–40%，只有仿真的一半。这组对比是全文对「视觉不可或缺」这一论点最硬的证据。</p><p>需要指出两处小问题：正文写「表 6 显示随间隙减小平均步数从 1.6 增到 4.3」，但该数据实际在表 5；另外表 2 里 VTLA 在多档上步数<strong>多于</strong>基线（0.6 mm 时 5.91 vs VLA 5.55 / TLA 5.48；1.0 mm 时 4.64 vs VLA 3.28），所以「更高效率」这一结论只在真机的五边形一格上成立，不宜推广。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：VTLA 把触觉图像序列折叠成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 网格作为「时序增强 token」，并把视觉放在触觉之后、紧邻动作输出，以对抗语言模型的近因偏置。骨干 Qwen2-VL-7B，先用 28,000 条仿真样本做 NTP 微调，再用 2,400 条自采样偏好对做 DPO，把连续控制所需的距离信息以偏序形式注回分类损失。仿真中 0.6 mm 间隙成功率 90%，显著高于 Diffusion Policy 的 22%；真机零微调下 95–100%。触觉相对纯视觉 VLA 的增量在数据集指标上只有约 1 个百分点，但在最紧间隙与 OOD 形状上值 10 个百分点。DPO 的收益全在 OOD（27.0→31.4），ID 上没有提升。</p><p><strong>三句话版</strong>：把触觉塞进 VLM 的关键不在融合模块，而在 token 排布顺序与时序折叠方式。分类损失训连续控制会丢掉「错多远」，用自采样偏好对补回来能改善泛化但改不了域内拟合。纯触觉方案的 Sim2Real 落差远大于带视觉方案。</p><p><strong>一句话版</strong>：视觉负责把销钉送到孔口，触觉负责最后半毫米，而顺序摆错了 LLM 就听不见视觉。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>自研视触觉仿真器生成的触觉图像与真实 GelStereo 2.0 的输出足够同分布</strong>。全部训练数据都是仿真产的，真机零微调直接部署，若这条不成立，整个 Sim2Real 结论都失效。</p><p>论文提供的证据是正面的：VTLA 真机 95–100%，与仿真持平甚至更高。但同一批实验里藏着一个强烈的反向信号 —— <strong>TLA（纯触觉）从仿真的 80% 掉到真机的 30–40%</strong>。TLA 和 VTLA 用的是同一个仿真器、同一套触觉数据。如果触觉的 sim-to-real gap 真的可忽略，TLA 不应该掉一半。更自洽的读法是：<strong>触觉仿真存在明显的域差，只是 VTLA 里视觉这条通路把它兜住了</strong>。作者在讨论 TLA 时也倾向这个解释（「需要更先进的 Sim2Real 迁移方法」）。</p><p>这条推断如果成立，代价很大：它意味着 VTLA 在真机上的高成功率可能主要由视觉支撑，触觉的实际贡献被域差侵蚀，而论文缺少一个能直接检验的对照 —— <strong>真机上的 VTLA 消融</strong>（例如把触觉输入置零或换成随机图，看成功率掉多少）。仿真里的 VLA-vs-VTLA 对比无法替代它，因为仿真里触觉没有域差。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只需一台带指尖视触觉传感器的机械臂或现成数据：</p><ul><li><strong>数据</strong>：不需要复现整个 28K 仿真数据集。取任一公开视触觉插孔数据集（或用 Isaac Gym 自采 3–5K 条单一形状样本），间隙固定 1.0 mm。</li><li><strong>实现</strong>：用同一个 VLM 骨干（可以缩到 2B 档）训四个变体，只改 token 排布：（i）触觉→视觉→文本（本文的 VGTE 顺序）；（ii）视觉→触觉→文本；（iii）触觉帧按视频通路输入而非 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 网格折叠；（iv）无触觉。</li><li><strong>测量</strong>：GCR 与逐维 L1，外加仿真成功率。</li><li><strong>判据</strong>：本文的第一项技术贡献 VGTE 由「视觉后置」与「时序折叠」两部分构成，而<strong>全文没有任何单独消融它的实验</strong>（表 4 只消融了 DPO）。若 (i) 与 (ii) 差距不显著，则「近因偏置」这一动机不成立，VLA→VTLA 的全部增益就只能归因于「多了触觉这个模态」；若 (i) 与 (iii) 差距不显著，则时序折叠也只是实现细节。这个实验的成本远低于复现全系统，却能判定本文一半的贡献是否真实。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的替代解释是：<strong>VTLA 相对 VLA 的全部优势可能来自「多一个输入模态带来的正则化 / 容量利用」，而非触觉承载的接触信息</strong>。支持这一解释的证据是 ID-GCR 上仅 1.2 个百分点的差距，以及 L1-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 上 VLA 反而更好。</p><p>判决性实验：给 VLA 也补一路<strong>信息无关的额外图像输入</strong>（例如把腕部相机图做一次强扰动后的副本，或一张固定的噪声图，或触觉图的时间打乱版本），保持 token 数与位置完全一致。若这个「假触觉 VLA」也能把 0.6 mm 成功率从 80% 拉到接近 90%，那么触觉本身的贡献就被证伪了。反过来，若「触觉图时间打乱」这一变体明显掉分，则说明模型确实在用触觉的<strong>时序结构</strong>，VGTE 的动机得到独立支持。这个对照本文完全没有做，而它的成本极低。</p><p>另一条可预期的失败场景：<strong>圆销</strong>。表 3 显示三种 LLM 方法在圆销上几乎并列（VLA 94、TLA 92、VTLA 92，VTLA 反而不是最高），作者归因于圆形的几何各向同性使任务本身更简单。反过来说，这也意味着当接触信息与「该往哪转」无关时，触觉通路会退化为噪声。可以预测：在<strong>高度对称或表面极光滑</strong>的工件上，VTLA 相对 VLA 不会有优势，甚至可能因为触觉信号无判别力而略差。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文的偏好对由「与真值动作的 L1 距离」机械生成，候选只来自两组采样配置。作者自己发现 1k→2k 无收益，并推断多样性比数量更重要。这暴露了一个更深的问题：<strong>偏好信号的语义完全由「离真值多近」定义，而插孔任务里「离真值近」并不等于「更容易成功」</strong>。一个偏离真值但沿着孔壁滑入的动作，可能比一个更接近真值却卡住的动作更好。</p><p><strong>(b) 新 framing 与可借的工具</strong>：把偏好的来源从「动作空间的距离」换成<strong>接触事件的可恢复性（recoverability）</strong> —— 即从执行该动作后的状态出发，还需要几步才能插入成功。这不是加一个奖励项，而是换一个偏序的定义域：从动作空间搬到状态-价值空间。可借的工具来自离线 RL 里的「hindsight 重标注」与「时间距离度量」（temporal distance / quasimetric RL）：用仿真里已有的 rollout 直接标注每个状态到成功的剩余步数，把它当作偏好的排序键。这样偏好对不再需要真值动作，也就自动适用于没有专家轨迹的新形状与新间隙。</p><p><strong>(c) 第一个实验</strong>：在现有仿真环境里，对同一批 SFT 模型采样的候选动作，用两种键构造偏好对 —— 键 A = 与真值动作的 L1 距离（本文做法），键 B = 执行该动作后到成功所需的剩余尝试次数（可由仿真器回放得到）。两者各训一个 DPO，在 OOD 形状与更紧间隙（例如 0.4 mm，训练分布之外）上比较成功率与平均步数。若 B 在 OOD 上明显胜出，说明偏好的语义比偏好的数量更关键，也为「无专家轨迹的新任务」打开了口子。</p>',54)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
